"""Apply a JSON Patch (RFC 6902) to a JSON document. See task.md."""

from __future__ import annotations

import copy
import re
from typing import Any


class PatchError(ValueError):
    """Raised when a patch is malformed or cannot be applied."""


_OPS = ("add", "remove", "replace", "move", "copy", "test")
_ARRAY_INDEX = re.compile(r"0|[1-9][0-9]{0,17}")
_BAD_ESCAPE = re.compile(r"~(?![01])")


def apply(document: Any, patch: list[dict]) -> Any:
    """Return the result of applying `patch` to `document`."""
    if not isinstance(patch, list):
        raise PatchError("patch must be a list")
    root = copy.deepcopy(document)
    for operation in copy.deepcopy(patch):
        root = _apply_operation(root, operation)
    return root


def _apply_operation(root: Any, operation: Any) -> Any:
    if not isinstance(operation, dict):
        raise PatchError("each operation must be an object")
    name = operation.get("op")
    if not isinstance(name, str) or name not in _OPS:
        raise PatchError(f"unknown operation {name!r}")
    target = _pointer(_string(operation, "path"))

    if name == "add":
        return _add(root, target, _value(operation))
    if name == "replace":
        return _replace(root, target, _value(operation))
    if name == "remove":
        _remove(root, target)
        return root
    if name == "test":
        if not _equal(_walk(root, target), _value(operation)):
            raise PatchError("test failed")
        return root

    source = _pointer(_string(operation, "from"))
    if name == "copy":
        return _add(root, target, copy.deepcopy(_walk(root, source)))
    return _move(root, source, target)


def _pointer(text: str) -> list[str]:
    if text == "":
        return []
    if not text.startswith("/"):
        raise PatchError(f"invalid JSON pointer {text!r}")
    tokens = []
    for raw in text[1:].split("/"):
        if _BAD_ESCAPE.search(raw):
            raise PatchError(f"invalid escape in JSON pointer {text!r}")
        tokens.append(raw.replace("~1", "/").replace("~0", "~"))
    return tokens


def _string(operation: dict, key: str) -> str:
    value = operation.get(key)
    if not isinstance(value, str):
        raise PatchError(f"operation member {key!r} must be a string")
    return value


def _value(operation: dict) -> Any:
    if "value" not in operation:
        raise PatchError("operation is missing 'value'")
    return operation["value"]


def _container(node: Any) -> dict | list:
    if isinstance(node, (dict, list)):
        return node
    raise PatchError("pointer descends into a non-container value")


def _index(token: str) -> int:
    if not _ARRAY_INDEX.fullmatch(token):
        raise PatchError(f"invalid array index {token!r}")
    return int(token)


def _walk(node: Any, tokens: list[str]) -> Any:
    for token in tokens:
        if isinstance(node, dict):
            if token not in node:
                raise PatchError(f"no member {token!r}")
            node = node[token]
        elif isinstance(node, list):
            index = _index(token)
            if index >= len(node):
                raise PatchError(f"array index {index} out of range")
            node = node[index]
        else:
            raise PatchError("pointer descends into a non-container value")
    return node


def _locate(root: Any, tokens: list[str]) -> tuple[dict | list, Any]:
    """Return the parent container and key of an existing location."""
    parent = _container(_walk(root, tokens[:-1]))
    key = tokens[-1]
    if isinstance(parent, dict):
        if key not in parent:
            raise PatchError(f"no member {key!r}")
        return parent, key
    index = _index(key)
    if index >= len(parent):
        raise PatchError(f"array index {index} out of range")
    return parent, index


def _add(root: Any, tokens: list[str], value: Any) -> Any:
    if not tokens:
        return value
    parent = _container(_walk(root, tokens[:-1]))
    key = tokens[-1]
    if isinstance(parent, dict):
        parent[key] = value
    elif key == "-":
        parent.append(value)
    else:
        index = _index(key)
        if index > len(parent):
            raise PatchError(f"array index {index} out of range")
        parent.insert(index, value)
    return root


def _replace(root: Any, tokens: list[str], value: Any) -> Any:
    if not tokens:
        return value
    parent, key = _locate(root, tokens)
    parent[key] = value
    return root


def _remove(root: Any, tokens: list[str]) -> Any:
    if not tokens:
        raise PatchError("cannot remove the whole document")
    parent, key = _locate(root, tokens)
    return parent.pop(key)


def _move(root: Any, source: list[str], target: list[str]) -> Any:
    _walk(root, source)
    if source == target:
        return root
    if target[: len(source)] == source:
        raise PatchError("cannot move a value into one of its own children")
    moved = _remove(root, source)
    return _add(root, target, moved)


def _equal(a: Any, b: Any) -> bool:
    if isinstance(a, list) and isinstance(b, list):
        return len(a) == len(b) and all(_equal(x, y) for x, y in zip(a, b))
    if isinstance(a, dict) and isinstance(b, dict):
        return a.keys() == b.keys() and all(_equal(a[k], b[k]) for k in a)
    if isinstance(a, bool) or isinstance(b, bool):
        return isinstance(a, bool) and isinstance(b, bool) and a == b
    if isinstance(a, (int, float)) and isinstance(b, (int, float)):
        return a == b
    return type(a) is type(b) and a == b
